const {
  withAppBuildGradle,
  withGradleProperties,
} = require('expo/config-plugins');

/**
 * The android/ folder is generated by `expo prebuild` and is not committed, so
 * the release signing config cannot live there — it is re-applied on every
 * prebuild by this plugin instead.
 *
 * Credentials come from the environment (see scripts/build-apk.sh, which loads
 * credentials/android-release.env). When they are missing the release build
 * keeps the debug signing config, so `expo prebuild` still works for anyone who
 * only wants to run the app.
 */

const PROPS = {
  storeFile: 'MOBILE_HACKATHON_RELEASE_STORE_FILE',
  storePassword: 'MOBILE_HACKATHON_RELEASE_STORE_PASSWORD',
  keyAlias: 'MOBILE_HACKATHON_RELEASE_KEY_ALIAS',
  keyPassword: 'MOBILE_HACKATHON_RELEASE_KEY_PASSWORD',
};

const readCredentials = () => {
  const storeFile = process.env.ANDROID_KEYSTORE_PATH;
  const storePassword = process.env.ANDROID_KEYSTORE_PASSWORD;
  const keyAlias = process.env.ANDROID_KEY_ALIAS;
  const keyPassword = process.env.ANDROID_KEY_PASSWORD ?? storePassword;

  if (!storeFile || !storePassword || !keyAlias) return null;

  return {
    storeFile: require('node:path').resolve(storeFile),
    storePassword,
    keyAlias,
    keyPassword,
  };
};

const SIGNING_CONFIG = `
        release {
            if (project.hasProperty('${PROPS.storeFile}')) {
                storeFile file(${PROPS.storeFile})
                storePassword ${PROPS.storePassword}
                keyAlias ${PROPS.keyAlias}
                keyPassword ${PROPS.keyPassword}
            }
        }`;

const withReleaseSigningConfig = (config) =>
  withAppBuildGradle(config, (cfg) => {
    if (!readCredentials()) return cfg;

    let contents = cfg.modResults.contents;

    if (!contents.includes('signingConfigs {')) {
      throw new Error(
        '[with-android-release-signing] no signingConfigs block in app/build.gradle',
      );
    }

    if (!contents.includes(`${PROPS.storeFile}`)) {
      contents = contents.replace(
        'signingConfigs {',
        `signingConfigs {${SIGNING_CONFIG}`,
      );
    }

    // The template signs release with the debug key; point it at ours.
    contents = contents.replace(
      /(release\s*\{[^}]*?signingConfig\s+signingConfigs\.)debug/,
      '$1release',
    );

    if (
      !/release\s*\{[^}]*?signingConfig\s+signingConfigs\.release/.test(
        contents,
      )
    ) {
      throw new Error(
        '[with-android-release-signing] could not point release build at the release key',
      );
    }

    cfg.modResults.contents = contents;
    return cfg;
  });

const withReleaseGradleProperties = (config) =>
  withGradleProperties(config, (cfg) => {
    const credentials = readCredentials();
    if (!credentials) return cfg;

    const entries = Object.entries(PROPS).map(([field, key]) => ({
      type: 'property',
      key,
      value: credentials[field],
    }));

    cfg.modResults = [
      ...cfg.modResults.filter(
        (item) =>
          item.type !== 'property' || !Object.values(PROPS).includes(item.key),
      ),
      ...entries,
    ];

    return cfg;
  });

module.exports = (config) =>
  withReleaseSigningConfig(withReleaseGradleProperties(config));
